251: // hasNextCommittedEnts returns if there is any available entries for execution.
252: // This is a fast check without heavy raftLog.slice() in nextCommittedEnts().
253: func (l *raftLog) hasNextCommittedEnts(allowUnstable bool) bool {
254: 	if l.applyingEntsPaused {
255: 		// Entry application outstanding size limit reached.
256: 		return false
257: 	}
258: 	if l.hasNextOrInProgressSnapshot() {
